def create_default_farms(apps, schema_editor):
    Profile = apps.get_model("accounts", "Profile")
    Farm = apps.get_model("accounts", "Farm")
    database = schema_editor.connection.alias
    admins = list(Profile.objects.using(database).filter(role="admin"))
    farms_by_owner = {}

    for admin in admins:
        farm, _ = Farm.objects.using(database).get_or_create(
            owner_id=admin.pk,
            name="Mi Finca",
        )
        farms_by_owner[admin.pk] = farm

    for profile in Profile.objects.using(database).filter(role="trabajador"):
        owner_id = profile.created_by_id
        if owner_id not in farms_by_owner and len(admins) == 1:
            owner_id = admins[0].pk
        farm = farms_by_owner.get(owner_id)
        if farm:
            profile.farm_id = farm.pk
            profile.save(using=database, update_fields=["farm"])


